183	func doJSON(t *testing.T, h http.Handler, method, path string, body any) *httptest.ResponseRecorder {
184		t.Helper()
185		var reader *bytes.Reader
186		if body != nil {
187			raw, err := json.Marshal(body)
188			if err != nil {
189				t.Fatalf("marshal: %v", err)
190			}
191			reader = bytes.NewReader(raw)
192		} else {
193			reader = bytes.NewReader(nil)
194		}
195		req := httptest.NewRequest(method, path, reader)
196		req.Header.Set("Content-Type", "application/json")
197		rec := httptest.NewRecorder()
198		h.ServeHTTP(rec, req)
199		return rec
200	}
