736	// TestCapacityExactOverHTTP 覆盖需求中的核心场景：通过真实 HTTP JSON 文本
737	// 提交容量，验证响应与列表中的数字逐位一致。
738	func TestCapacityExactOverHTTP(t *testing.T) {
739		t.Run("tiny fractional part is rejected", func(t *testing.T) {
