744			}
745			if msg := decodeBody(t, rec)["error"].(string); !strings.Contains(msg, "正整数") {
746				t.Fatalf("error must say capacity must be a positive integer, got %q", msg)
747			}
748			assertEmptyVenueList(t, h)
749		})
750	
751		t.Run("1e-1 is rejected", func(t *testing.T) {
752			_, h := newTestServer(t)
753			rec := postRaw(t, h, validBodyWithCapacity("1e-1"))
754			if rec.Code != http.StatusBadRequest {
755				t.Fatalf("status = %d, want 400", rec.Code)
756			}
757			assertEmptyVenueList(t, h)
758		})
759	
760		for _, lit := range []string{"120", "120.0", "1.2e2"} {
761			t.Run("valid integer literal "+lit, func(t *testing.T) {
762				_, h := newTestServer(t)
763				rec := postRaw(t, h, validBodyWithCapacity(lit))
764				if rec.Code != http.StatusCreated {
765					t.Fatalf("status = %d, want 201, body = %s", rec.Code, rec.Body.String())
766				}
767				if got := decodeBody(t, rec)["venue"].(map[string]any)["capacity"].(float64); got != 120 {
768					t.Fatalf("capacity = %v, want 120", got)
