789			}
790			// 用 UseNumber 解析，避免测试端 float64 再次舍入。
791			var decoded struct {
792				Venue struct {
793					Capacity json.Number `json:"capacity"`
794				} `json:"venue"`
795			}
796			if err := json.Unmarshal(rec.Body.Bytes(), &decoded); err != nil {
797				t.Fatal(err)
798			}
799			if decoded.Venue.Capacity.String() != exact {
800				t.Fatalf("response capacity = %q, want %s", decoded.Venue.Capacity, exact)
801			}
802	
803			// 列表中必须是同一个容量。
804			listRec := doJSON(t, h, http.MethodGet, "/api/venues", nil)
805			var listed struct {
806				Venues []struct {
807					Capacity json.Number `json:"capacity"`
808				} `json:"venues"`
809			}
810			if err := json.Unmarshal(listRec.Body.Bytes(), &listed); err != nil {
811				t.Fatal(err)
812			}
813			if len(listed.Venues) != 1 || listed.Venues[0].Capacity.String() != exact {
814				t.Fatalf("listed capacity = %+v, want exactly [%s]", listed.Venues, exact)
815			}
816	
817			// 持久化文件里也必须逐位准确。
818			raw, err := os.ReadFile(s.path)
819			if err != nil {
820				t.Fatal(err)
821			}
822			if !strings.Contains(string(raw), exact) {
823				t.Fatalf("stored file must contain exact integer:\n%s", raw)
824			}
825		})
826	
827		t.Run("same integer written with exponent notation", func(t *testing.T) {
828			_, h := newTestServer(t)
829			rec := postRaw(t, h, validBodyWithCapacity("9.007199254740993e15"))
830			if rec.Code != http.StatusCreated {
831				t.Fatalf("status = %d, want 201, body = %s", rec.Code, rec.Body.String())
832			}
833			if !strings.Contains(rec.Body.String(), "9007199254740993") {
834				t.Fatalf("exponential integer must be stored exactly: %s", rec.Body.String())
835			}
836		})
