838		t.Run("integer outside supported range is rejected as 400", func(t *testing.T) {
839			s, h := newTestServer(t)
840			for _, lit := range []string{
841				"9223372036854775808",          // 2^63
842				"999999999999999999999999",     // 远超范围
843				"1e100",                        // 指数写法的超大整数
844				"9007199254740993000000000000", // 超过 int64
845			} {
846				rec := postRaw(t, h, validBodyWithCapacity(lit))
847				if rec.Code != http.StatusBadRequest {
848					t.Fatalf("%s: status = %d, want 400, body = %s", lit, rec.Code, rec.Body.String())
849				}
850				if msg := decodeBody(t, rec)["error"].(string); !strings.Contains(msg, "超出支持范围") {
851					t.Fatalf("%s: error must explain out-of-range, got %q", lit, msg)
852				}
