864		t.Run("zero negative string boolean null and missing are rejected", func(t *testing.T) {
865			cases := map[string]string{
866				"zero":        validBodyWithCapacity("0"),
867				"negative":    validBodyWithCapacity("-5"),
868				"string":      `{"name":"x","capacity":"120","timezone":"UTC","weeklyHours":[]}`,
869				"boolean":     `{"name":"x","capacity":true,"timezone":"UTC","weeklyHours":[]}`,
870				"null":        `{"name":"x","capacity":null,"timezone":"UTC","weeklyHours":[]}`,
871				"missing":     `{"name":"x","timezone":"UTC","weeklyHours":[]}`,
