  var setter;
  if (el instanceof HTMLSelectElement || el instanceof HTMLTextAreaElement) {
    setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
  } else {
    setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
  }
