}
function __hbWaitFor(predicateSource, timeoutMs) {
  return new Promise(function (resolve, reject) {
    var predicate;
    try { predicate = eval('(' + predicateSource + ')'); } catch (e) { reject(e); return; }
    var deadline = Date.now() + timeoutMs;
    (function tick() {
      var ok = false, value;
      try { value = predicate(); ok = true; } catch (e) { value = undefined; }
      if (ok && value) return resolve(value);
      if (Date.now() > deadline) return reject(new Error('condition timeout: ' + predicateSource));
