    });
  }
}

let chrome, devtoolsBase, browserWs;

async function mainLoop(req) {
  switch (req.method) {
    case 'open': {
      const target = await newTarget(req.url);
      const sessionId = await browserWs.attach(target.id);
      const session = browserWs.session(sessionId);
      await session.send('Page.enable');
      await session.send('Runtime.enable');
      await session.send('Page.addScriptToEvaluateOnNewDocument', {
        script:
          'window.__hbRequests = [];' +
          'var __hbOfetch = window.fetch;' +
          'window.fetch = function (input, init) {' +
          '  var record = {' +
          '    url: typeof input === "string" ? input : String(input && input.url || input),' +
          '    method: (init && init.method) || (input && input.method) || "GET",' +
          '    body: init && Object.prototype.hasOwnProperty.call(init, "body") ? init.body : null' +
          '  };' +
          '  window.__hbRequests.push(record);' +
          '  return __hbOfetch.apply(this, arguments);' +
          '};',
      });
      // 重新导航一次，保证注入脚本在页面脚本之前运行。
      await session.send('Page.navigate', { url: req.url });
      await sleep(400);
      // 下发页面内助手。
      await evaluateOn(session, HELPER_SCRIPT);
      sessionsById.set(req.name || target.id, { session, targetId: target.id });
      writeResponse({ id: req.id, ok: true, result: { session: req.name || target.id } });
      return;
    }
    case 'eval': {
      const entry = sessionsById.get(req.name);
      if (!entry) throw new Error('unknown session: ' + req.name);
      const wrapped = `(async () => { ${req.fn} })()`;
      // fn 是一个 async 箭头/函数体的完整源码，例如 "async () => {...}"。
      const expression = `(${req.fn})()`;
      const value = await evaluateOn(entry.session, expression);
      writeResponse({ id: req.id, ok: true, result: value });
      return;
    }
    case 'reload': {
      const entry = sessionsById.get(req.name);
      if (!entry) throw new Error('unknown session: ' + req.name);
      await entry.session.send('Page.navigate', { url: entry.lastUrl || req.url });
      await sleep(400);
      await evaluateOn(entry.session, HELPER_SCRIPT);
      writeResponse({ id: req.id, ok: true });
      return;
    }
    case 'close': {
      writeResponse({ id: req.id, ok: true });
      await shutdown(0);
      return;
    }
    default:
      throw new Error('unknown method: ' + req.method);
  }
}

const sessionsById = new Map();

shutdown = async function (code, reason) {
  if (shutdown.done) return;
  shutdown.done = true;
  try { browserWs && await browserWs.close(); } catch { /* 忽略 */ }
  if (chrome) {
    chrome.kill('SIGKILL');
    setTimeout(() => process.exit(code), 100).unref();
  } else {
    process.exit(code);
  }
  if (reason) console.error('shutdown: ' + reason);
};
let shutdown = Object.assign(async function () {}, { done: false });

main().catch(async err => {
  console.error('cdp.mjs fatal: ' + err.message);
  await shutdown(1, err.message);
});

